sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 center;
uniform float frequency;
uniform float strength;
uniform float phase;
uniform float radius;
uniform float feather;
half4 main(float2 coord) {
    float m = min(size.x, size.y);
    float2 d = coord - center * size;
    float r = length(d) / m;
    if (r <= 0.0) return image.eval(coord);
    float edge = max(feather * radius, 0.0005);
    float fade = 1.0 - smoothstep(radius - edge, radius, r);
    float wave = sin(6.2831853 * (frequency * r - phase));
    return image.eval(coord + d / (r * m) * wave * strength * m * 0.5 * fade);
}
